CREATE COLUMN TABLE "TEST_AP"."OACG" ("AbsId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(40) NOT NULL , "Source" NVARCHAR(1) DEFAULT 'B' NOT NULL , "Locked" NVARCHAR(1) DEFAULT 'N', "DateSource" NVARCHAR(1), "UserSign" NVARCHAR(6), PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OACG_SECOND" ON "TEST_AP"."OACG" ( "Source" ASC, "Name" ASC )